import{_ as n,C as a,o,c as l,a2 as t,E as i}from"./chunks/framework.CDpkVv68.js";const y=JSON.parse('{"title":"Item Quality / Masterworks","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/items/item-quality.md","filePath":"en/guide/items/item-quality.md"}'),d={name:"en/guide/items/item-quality.md"};function c(u,e,h,m,p,f){const r=a("WikiVisual"),s=a("WikiBadges");return o(),l("div",null,[e[0]||(e[0]=t('<h1 id="item-quality-masterworks" tabindex="-1">Item Quality / Masterworks <a class="header-anchor" href="#item-quality-masterworks" aria-label="Permalink to &quot;Item Quality / Masterworks&quot;">​</a></h1><p><strong>Status:</strong> Proposed · Not established as playable.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Quality means doing an item’s job well: <a href="/Syrolands-Public/en/guide/glossary.html#handling">handling</a>, <a href="/Syrolands-Public/en/guide/glossary.html#consistency">consistency</a>, integrity and lasting function.</li><li><a href="/Syrolands-Public/en/guide/characters/skills.html">Skill</a>, <a href="/Syrolands-Public/en/guide/characters/techniques.html">techniques</a>, materials and execution shape results; luck plays a small role.</li><li>A <a href="/Syrolands-Public/en/guide/glossary.html#masterwork">Masterwork</a> is not automatically magical, and excellent equipment can still be lost.</li></ul><p><span id="quality-means-doing-a-job-well"></span><span id="the-proposed-categories"></span><span id="what-you-might-notice"></span><span id="special-properties-and-memorable-items"></span><span id="related-systems"></span></p>',5)),i(r,{"asset-id":"spot-item-quality"}),i(s,{ids:"icon-masterwork"}),e[1]||(e[1]=t('<h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Activity</th><th>What you do</th></tr></thead><tbody><tr><td>Shared quality</td><td>Crafted equipment and monster drops use a compatible quality language.</td></tr><tr><td>Weapon identity</td><td>Quality improves a weapon’s own role; a fine dagger does not become a war hammer.</td></tr><tr><td>Masterwork</td><td>An extremely rare technical masterpiece, not a routine result at skill 100.</td></tr><tr><td><a href="/Syrolands-Public/en/guide/glossary.html#latent-property">Latent Property</a></td><td>Rare inactive resonance might awaken through exceptional use, a place, a creature or a ritual.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Compared with classic UO <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Permalink to &quot;Compared with classic UO&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Classic UO</th><th>Syrolands direction</th></tr></thead><tbody><tr><td>Exceptional crafted equipment already rewards craftsmanship.</td><td>Quality also emphasizes handling, consistency and retained function.</td></tr><tr><td>Magical properties and crafted quality are familiar equipment ideas.</td><td>Rare traits need justification and trade-offs; technical excellence does not guarantee magic.</td></tr></tbody></table><p>Comparison uses familiar UO crafting loops; the official references also cover later expansions. <a href="https://uo.com/wiki/ultima-online-wiki/skills/blacksmithing/" target="_blank" rel="noreferrer">Blacksmithing</a>.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>An Exceptional longsword could balance better and hold its edge longer than a Common one, while the Common sword remains useful. A Frostwood bow awakening after a cold-related event is only an illustration, not a guaranteed recipe.</p><h2 id="progression-and-trade-offs" tabindex="-1">Progression and trade-offs <a class="header-anchor" href="#progression-and-trade-offs" aria-label="Permalink to &quot;Progression and trade-offs&quot;">​</a></h2><ul><li>Crude, Common, Fine, Exceptional and Superior describe progressively better workmanship. Masterwork remains rare; Singular / Relic describes unusual history or behavior, not a routine next tier.</li><li>Ordinary excellent equipment should stay competitive. Traits, awakening conditions and future resonant sets remain undecided; none grants insurance or loot protection.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/professions/overview.html">Profession System</a> · <a href="/Syrolands-Public/en/guide/professions/blacksmithing.html">Blacksmithing</a> · <a href="/Syrolands-Public/en/guide/professions/carpentry.html">Carpentry / Bowmaking</a></p><h2 id="full-design-specification" tabindex="-1">Full design specification <a class="header-anchor" href="#full-design-specification" aria-label="Permalink to &quot;Full design specification&quot;">​</a></h2><p><a href="/Syrolands-Public/en/game-design/items/itemization-and-craft-quality.html">Item Quality / Masterworks</a></p>',13))])}const b=n(d,[["render",c]]);export{y as __pageData,b as default};
